from pathlib import Path
import re

JS=Path('jordan/jordan-pwa.js')
INDEX=Path('jordan/index.html')
SW=Path('jordan/sw.js')

s=JS.read_text(encoding='utf-8')

old="""async function translateEnAr(text){const clean=String(text||'').replace(/\\s+/g,' ').trim();if(!clean)return '';const key='tr:'+clean.toLowerCase();const cached=await enrichCacheGet(key);if(typeof cached==='string')return cached;try{const j=await fetchJson('https://api.mymemory.translated.net/get?q='+encodeURIComponent(clean)+'&langpair=en%7Car',8500);const out=String(j?.responseData?.translatedText||'').trim();if(out&&out.toLowerCase()!==clean.toLowerCase()){await enrichCacheSet(key,out);return out}}catch(_){}return ''}
"""
new="""function sleep(ms){return new Promise(resolve=>setTimeout(resolve,ms))}
function splitTranslationChunks(text,max=1100){const clean=String(text||'').replace(/\\s+/g,' ').trim();if(clean.length<=max)return clean?[clean]:[];const sentences=clean.split(/(?<=[.!?])\\s+/),out=[];let buf='';for(const part of sentences){if(part.length>max){if(buf){out.push(buf);buf=''}for(let i=0;i<part.length;i+=max)out.push(part.slice(i,i+max));continue}if(!buf)buf=part;else if((buf+' '+part).length<=max)buf+=' '+part;else{out.push(buf);buf=part}}if(buf)out.push(buf);return out}
async function googleTranslateEnAr(clean){const j=await fetchJson('https://translate.googleapis.com/translate_a/single?client=gtx&sl=en&tl=ar&dt=t&q='+encodeURIComponent(clean),12000);const out=Array.isArray(j?.[0])?j[0].map(x=>String(x?.[0]||'')).join('').trim():'';return out&&out.toLowerCase()!==clean.toLowerCase()?out:''}
async function myMemoryTranslateEnAr(clean){const j=await fetchJson('https://api.mymemory.translated.net/get?q='+encodeURIComponent(clean)+'&langpair=en%7Car',10000);const out=String(j?.responseData?.translatedText||'').trim();return out&&out.toLowerCase()!==clean.toLowerCase()?out:''}
async function translateEnAr(text){const clean=String(text||'').replace(/\\s+/g,' ').trim();if(!clean)return '';const key='tr:'+clean.toLowerCase();const cached=await enrichCacheGet(key);if(typeof cached==='string'&&cached.trim())return cached;const chunks=splitTranslationChunks(clean),translated=[];for(const chunk of chunks){let out='';for(let attempt=0;attempt<3&&!out;attempt++){try{out=await googleTranslateEnAr(chunk)}catch(_){}if(!out){try{out=await myMemoryTranslateEnAr(chunk)}catch(_){}}if(!out)await sleep(600*(attempt+1))}if(!out)return '';translated.push(out);if(chunks.length>1)await sleep(180)}const final=translated.join(' ').trim();if(final){await enrichCacheSet(key,final);return final}return ''}
async function mapBookTranslations(list,fn,onProgress){const workers=Math.max(1,Math.min(3,Number(navigator.hardwareConcurrency||2)));let done=0,failed=0;for(let i=0;i<list.length;i+=workers){const batch=list.slice(i,i+workers);const results=await Promise.all(batch.map(async item=>{try{return await fn(item)}catch(_){return false}}));failed+=results.filter(x=>!x).length;done+=batch.length;await onProgress?.(done,list.length,failed);await sleep(260);await idleYield()}return {done,failed}}
function renderBookTranslationResults(list,mode,pageIndex=0){const r=ROOT.querySelector('#btr');if(!r)return;const per=60,totalPages=Math.max(1,Math.ceil(list.length/per)),page=Math.max(0,Math.min(pageIndex,totalPages-1)),slice=list.slice(page*per,(page+1)*per),pending=list.filter(x=>mode==='words'?!x.meaning:!x.translation).length;const pager=`<div class=\"bt-pager\"><button class=\"j-btn secondary bt-prev\" ${page===0?'disabled':''}>السابق</button><span class=\"bt-page-info\">${page+1} / ${totalPages}</span><button class=\"j-btn secondary bt-next\" ${page===totalPages-1?'disabled':''}>التالي</button></div>`;const body=mode==='words'?slice.map(x=>`<div class=\"j-word\"><button class=\"j-btn light j-speak\" data-speak=\"${esc(x.word)}\">🔊</button><div><div class=\"j-word-en\">${esc(x.word)}</div><div class=\"j-word-ar\">${esc(x.meaning||'بانتظار الترجمة')}</div><div class=\"j-meta\">ص ${x.page}</div></div><span></span></div>`).join(''):slice.map(x=>`<div class=\"j-word\"><button class=\"j-btn light j-speak\" data-speak=\"${esc(x.text)}\">🔊</button><div><div class=\"j-example\">${esc(x.text)}</div><div class=\"j-word-ar\">${esc(x.translation||'بانتظار الترجمة')}</div><div class=\"j-meta\">ص ${x.page} • ${mode==='paragraphs'?'فقرة':'جملة'}</div></div><span></span></div>`).join('');r.innerHTML=(pending?`<div class=\"j-note\">متبقي للترجمة: ${pending}. يمكن إعادة المحاولة لاحقًا بدون فقدان ما تم إنجازه.</div>`:'')+pager+body+pager;r.querySelectorAll('.bt-prev').forEach(b=>b.onclick=()=>renderBookTranslationResults(list,mode,page-1));r.querySelectorAll('.bt-next').forEach(b=>b.onclick=()=>renderBookTranslationResults(list,mode,page+1));bindSpeak()}
"""
if old not in s:
    if 'function renderBookTranslationResults' not in s:
        raise SystemExit('translateEnAr marker not found')
else:
    s=s.replace(old,new,1)

start=s.find('async function translateBookRun(mode){')
end=s.find('\nfunction render(){',start)
if start<0 or end<0:
    raise SystemExit('translateBookRun markers missing')
replacement=r'''async function translateBookRun(mode){const f=ROOT.querySelector('#btf')?.files?.[0],p=ROOT.querySelector('#btp'),r=ROOT.querySelector('#btr');if(!f){alert('اختر ملف PDF أولًا');return}if(!['words','sentences','paragraphs'].includes(mode)){alert('اختر نوع الترجمة أولًا');return}r.innerHTML='';let saved=await loadWorkSession(f,mode);const words=new Map(),items=[],seen=new Set();let pages=0,startPage=1;if(saved){pages=Number(saved.pages||0);startPage=Math.max(1,pages+1);for(const x of Array.isArray(saved.items)?saved.items:[]){if(mode==='words')words.set(x.word,x);else{items.push(x);seen.add(String(x.text||'').toLowerCase())}}p.innerHTML=`<div class="j-note">تم العثور على حفظ تلقائي سابق: ${pages} صفحة. سيتم الاستكمال ثم إعادة محاولة العناصر غير المترجمة.</div>`}
try{await extractPdf(f,async(text,pi,total)=>{if(pi<startPage)return;pages=pi;if(mode==='words'){for(const m of text.matchAll(/[A-Za-z][A-Za-z'-]*/g)){const raw=m[0];if(!validWord(raw,false))continue;const key=raw.toLowerCase();if(!words.has(key))words.set(key,{word:key,meaning:'',page:pi})}}else{const source=mode==='paragraphs'?paragraphList(text):sentenceList(text);for(const block of source){const key=block.toLowerCase();if(seen.has(key))continue;seen.add(key);items.push({text:block,translation:'',page:pi})}}const snapshot=mode==='words'?[...words.values()]:items;await saveWorkSession(f,mode,{pages:pi,totalPages:total,phase:'reading',items:snapshot});p.innerHTML=`<div class="j-progress"><div style="width:${Math.round(pi/total*40)}%"></div></div><p>قراءة الصفحة ${pi} من ${total} • تم الحفظ تلقائيًا</p>`});const list=mode==='words'?[...words.values()]:items;if(!list.length){p.innerHTML='<div class="j-note">لم يتم العثور على محتوى مناسب للترجمة.</div>';return}renderBookTranslationResults(list,mode,0);const pending=list.filter(x=>mode==='words'?!x.meaning:!x.translation);const doneBase=list.length-pending.length;if(!pending.length){await saveWorkSession(f,mode,{pages,phase:'complete',items:list,complete:true});p.innerHTML=`<div class="j-stats"><div class="j-stat">${pages} صفحة</div><div class="j-stat">${list.length} ${mode==='words'?'كلمة':mode==='sentences'?'جملة':'فقرة'}</div><div class="j-stat">✓ الترجمة مكتملة</div></div>`;return}await mapBookTranslations(pending,async item=>{if(mode==='words'){const x=await enrichVocabulary(item.word);if(x.meaning)item.meaning=x.meaning;return !!item.meaning}else{const tr=await translateEnAr(item.text);if(tr)item.translation=tr;return !!item.translation}},async(done,total,failed)=>{await saveWorkSession(f,mode,{pages,phase:'translating',items:list});const finished=doneBase+done;p.innerHTML=`<div class="j-progress"><div style="width:${40+Math.round(finished/Math.max(1,list.length)*60)}%"></div></div><p>الترجمة ${finished} من ${list.length} • حفظ تلقائي • فشل مؤقت ${failed}</p>`;if(done%24===0)renderBookTranslationResults(list,mode,0)});const remaining=list.filter(x=>mode==='words'?!x.meaning:!x.translation).length;await saveWorkSession(f,mode,{pages,phase:remaining?'partial':'complete',items:list,complete:remaining===0});p.innerHTML=`<div class="j-stats"><div class="j-stat">${pages} صفحة</div><div class="j-stat">${list.length} ${mode==='words'?'كلمة':mode==='sentences'?'جملة':'فقرة'}</div><div class="j-stat">✓ محفوظ تلقائيًا</div>${remaining?`<div class="j-stat">${remaining} بانتظار إعادة المحاولة</div>`:'<div class="j-stat">الترجمة مكتملة</div>'}</div>${remaining?'<button id="btRetryPending" class="j-btn bt-retry">إعادة محاولة غير المترجم</button>':''}`;renderBookTranslationResults(list,mode,0);const retry=ROOT.querySelector('#btRetryPending');if(retry)retry.onclick=()=>translateBookRun(mode)}catch(e){console.error(e);const list=mode==='words'?[...words.values()]:items;await saveWorkSession(f,mode,{pages,phase:'interrupted',items:list,error:String(e?.message||e)});renderBookTranslationResults(list,mode,0);p.innerHTML=`<div class="j-note">توقف العمل مؤقتًا، لكن تم حفظ ما تم إنجازه حتى الصفحة ${pages}. اضغط «ابدأ / أكمل الترجمة» لإعادة المحاولة دون البدء من الصفر.</div>`}}
'''
s=s[:start]+replacement+s[end:]
JS.write_text(s,encoding='utf-8')

idx=INDEX.read_text(encoding='utf-8')
idx=idx.replace('manifest.webmanifest?v=355','manifest.webmanifest?v=356').replace('jordan-pwa.css?v=355','jordan-pwa.css?v=356').replace('easy-english-v345-patch.css?v=355','easy-english-v345-patch.css?v=356').replace('jordan-pwa.js?v=355','jordan-pwa.js?v=356').replace("./sw.js?v=355-paragraph-autosave-1","./sw.js?v=356-translation-resilience-1")
INDEX.write_text(idx,encoding='utf-8')

sw=SW.read_text(encoding='utf-8')
sw=sw.replace("easy-english-ai-pwa-v355-paragraph-autosave","easy-english-ai-pwa-v356-translation-resilience").replace('jordan-pwa.css?v=355','jordan-pwa.css?v=356').replace('easy-english-v345-patch.css?v=355','easy-english-v345-patch.css?v=356').replace('jordan-pwa.js?v=355','jordan-pwa.js?v=356').replace('manifest.webmanifest?v=355','manifest.webmanifest?v=356')
SW.write_text(sw,encoding='utf-8')
